// zh-cn message catalog. Typed `Record<MessageId, string>` so a missing key from
// the en source-of-truth is a compile error (the completeness gate).
//
// LANGUAGE OWNER: @AngLee — Chinese values must be authoritative per the zh-cn
// glossary; keep "Agent" / "Computer" / "Raft" as product terms, no English
// plurals in CJK. Chinese has no count-plural distinction, so plural ICU uses a
// single `other` arm.

