  "migration.error.entryCountLimitExceededWithDetails": "工作区有 {count, number} 个文件和文件夹，迁移最多支持 {limit, number} 个。{paths, select, none {} other {大部分位于：{paths}。}}请让 Agent 删除不再需要的目录，或把它们写进 .raftmigrateignore，然后重试。",
  "migration.error.workspaceAlreadyExists": "目标计算机无法安装该 Agent，因为这个工作区已经存在。请确认哪个副本是当前版本，将冲突的工作区移走或备份后重试。Raft 不会自动删除它。",
  "migration.error.workspaceCompleteOldCopy": "目标计算机发现了这个工作区之前已完成的副本，因此在替换它之前停止了。请确认哪个副本是当前版本，将旧副本移走或备份后重试。Raft 不会自动删除它。",
  "migration.error.workspaceAlreadyExistsAt": "目标计算机上 {path} 已有工作区，所以 Agent 没有安装。请把这个目录改名或移走（比如在名字后面加个 .bak 就行），然后重新发起迁移。移走前先确认这份不是你还需要的副本——Raft 不会删除它，移走后它仍在那台计算机上。",
  "migration.error.workspaceCompleteOldCopyAt": "目标计算机上 {path} 是上一次迁移留下的完整副本，Raft 没有覆盖它就停了下来。请把这个目录改名或移走（比如在名字后面加个 .old 就行），然后重新发起迁移。移走前先确认哪个副本是当前版本——Raft 不会删除它，移走后它仍在那台计算机上。",
  "migration.error.controlManifestInvalid": "源计算机生成了目标计算机无法验证的传输元数据。请更新两台计算机上的 Raft Computer，然后重试。",
